import{z as d,x as p,o as r,c as A,q as l,j as i,D as n,d as t,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"分治","description":"","frontmatter":{"title":"分治","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/divide-conquer.md","filePath":"cs/divide-conquer.md","lastUpdated":1791413859000}'),h={name:"cs/divide-conquer.md"};function m(T,a,u,B,f,c){const o=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="分治" tabindex="-1">分治 <a class="header-anchor" href="#分治" aria-label="Permalink to &quot;分治&quot;">​</a></h1><div class="epigraph"><p>把问题切成同类子问题，递归解完再合并；代价由切法与合并共同决定。</p><footer>—— 据 Knuth, The Art of Computer Programming, vol. 3；CLRS 第 2、4 章整理</footer></div><p>上一课<a href="/cs/akra-bazzi">Akra–Bazzi 对照</a>已经能读 \\(T(n)=aT(n/b)+f(n)\\)。本课不重证三种情形。缺口是：递归式从哪来。数据结构课给了数组、树、图的表示，没有说「把规模对半切」是一种设计。本课只钉分治三步：分解、递归、合并；具体排序算法后课才写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环不变式适合<strong>同一数组上逐步扩大前缀</strong>。有些问题前缀扩不成：左右两半各自有解，合在一起才是原问题的解。若不会分解，就只剩 \\(O(n^2)\\) 的双重循环。缺口不是渐近记号，而是承认子问题与原问题同型，规模严格变小，合并是显式步骤。</p><p><span class="marginnote">直觉类比：数一大袋硬币，分治就是分给两个人各数一半，报回总数再相加——「数」是递归，「相加」是显式的合并步骤。要点是数半袋的办法和数全袋一模一样，只是规模严格变小，最后小到一两个硬币直接报数，这就是基准情形。</span></p><p>本课不引入动态规划。分治的子问题通常不相交或几乎不相交；重叠子问题是<a href="/cs/dynamic-programming">后课</a>的缺口。这里只要求：切完能递归，合完满足原问题的后置条件。</p><h3 id="分治不是「递归」的别名" tabindex="-1">分治不是「递归」的别名 <a class="header-anchor" href="#分治不是「递归」的别名" aria-label="Permalink to &quot;分治不是「递归」的别名&quot;">​</a></h3><p>递归是控制结构；分治是切问题的方式。深度优先搜索也递归，但不是按规模等分再合并答案。尾递归循环更不是分治。后课见到 <code>recurse(left); recurse(right); merge</code> 才叫本课的对象。</p><p><span class="marginnote">Knuth 把归并当作外存与内排的共同骨架。CLRS 用归并引入分治，再用主定理收阶。本课把「范式」从「某一个排序」里抽出来，避免下一课重讲切法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定如何把输入分成 \\(a\\) 块（常 \\(a=2\\)、\\(b=2\\)），对每块调用同一过程，再写合并。正确性：子问题规模小于 \\(n\\)，基准情形直接解；归纳假设子解正确，证明合并保持后置条件。代价：写出 \\(T(n)\\)，套主定理。</p>',12)),(r(),i(E,null,{default:n(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%A7%84%E6%A8%A1%20n%20%E7%9A%84%E9%97%AE%E9%A2%98%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E8%A7%A3%E6%88%90%20a%20%E5%9D%97%22%5D%0A%20%20SPLIT%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%0A%20%20REC%20--%3E%20MERGE%5B%22%E5%90%88%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20ANS%5B%22%E5%8E%9F%E9%97%AE%E9%A2%98%E7%9A%84%E8%A7%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"分解本身可以是 \\(\\Theta(1)\\)（中点下标）或 \\(\\Theta(n)\\)（复制到新数组）。合并可以是 \\(\\Theta(n)\\)（归并）或 \\(\\Theta(1)\\)（最大值在根）。主定理里的 \\(f\\) 就是分解加合并。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：归并排序切 2 块、合并花 \\(\\Theta(n)\\)，递归式就是 \\(T(n)=2T(n/2)+n\\)，主定理给出 \\(\\Theta(n\\log n)\\)。若合并只需 \\(\\Theta(1)\\)（比如只在两半里挑最大值），\\(T(n)=2T(n/2)+1\\) 就降成 \\(\\Theta(n)\\)。同一副骨架，\\(f\\) 决定最终阶。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"分治把空间也切开：每层可以新开缓冲，总额外空间常 \\(\\Theta(n)\\)；就地切（快排分区）把额外空间压到递归栈。本课不选定哪一种，只声明空间是合并策略的一部分。后课插入是循环，归并是分治，对照才有意义。",-1)),(r(),i(E,null,{default:n(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E8%A7%84%E6%A8%A1%20n%20%E7%9A%84%E9%97%AE%E9%A2%98%22%5D%20--%3E%20A%5B%22n%2F2%22%5D%0A%20%20L0%20--%3E%20B%5B%22n%2F2%22%5D%0A%20%20A%20--%3E%20C%5B%22n%2F4%22%5D%0A%20%20A%20--%3E%20D%5B%22n%2F4%22%5D%0A%20%20B%20--%3E%20E%5B%22n%2F4%22%5D%0A%20%20B%20--%3E%20F%5B%22n%2F4%22%5D%0A%20%20S%5B%22%E6%AF%8F%E5%B1%82%E5%90%88%E5%B9%B6%E6%80%BB%E9%87%8F%E9%83%BD%E6%98%AF%20n%EF%BC%8C%E5%85%B1%20log%E2%82%82%20n%20%E5%B1%82%EF%BC%8C%E5%90%88%E8%AE%A1%20%CE%98(n%20log%20n)%22%5D%0A%20%20L0%20-.-%3E%20S%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">读图：递归树是把 \\(T(n)=2T(n/2)+f(n)\\) 展开画出来——第一层花 \\(f(n)\\)，第二层两个子问题共花 \\(2f(n/2)\\)，往下每层加总。归并这类 \\(f\\) 是线性的，每层总量恒为 \\(n\\)，层数是 \\(\\log_2 n\\)，两数相乘就是总代价。</span></p><p>并行直觉（两半可同时算）本课点到为止：正确性不依赖并行；只是 \\(a\\) 个子问题在数据上不相依。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分治不保证比循环快。切得不均衡，主定理的 \\(b\\) 失效，最坏可以退回平方。也不自动处理图上的全局约束：最短路不是「左右两半的最短路再拼」。图算法仍走 BFS/松弛，不套本课模板。</p><p>后课默认：说到分治，就是分解–递归–合并，递归式用主定理读。插入与归并的对照是后课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分治 = 同类子问题 + 规模下降 + 显式合并。</li><li>正确性走递归归纳；代价走主定理。</li><li>子问题重叠不是本课；图上的全局最优也不是。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 2、4 章。</li></ul>',7))])}const g=d(h,[["render",m]]);export{_ as __pageData,g as default};
